import sys

data = sys.stdin.read().split()
n0 = int(data[0])
k = int(data[1])
M = k
def f(n):
    if n == 0:
        return (0, 1)
    a, b = f(n // 2)
    c = a * ((2 * b - a) % M) % M
    d = (a * a + b * b) % M
    return (c, d) if n % 2 == 0 else (d, (c + d) % M)
print(f(n0)[0] % M)

